from pathlib import Path
import json,csv,io,collections,hashlib
T=Path(__file__).resolve().parent;P=T.parents[4]
a=json.loads((T/'assignment.json').read_text());p=json.loads((T/'field-plan.json').read_text())['entries'];missing=[];empty=[]
def dh(v):return hashlib.sha256(json.dumps(v,ensure_ascii=False,sort_keys=True,separators=(',',':')).encode()).hexdigest()
def walk(v,p=''):
 if isinstance(v,dict) and v:
  for k,z in v.items():yield from walk(z,p+'/'+str(k).replace('~','~0').replace('/','~1'))
 elif isinstance(v,list) and v:
  for k,z in enumerate(v):yield from walk(z,p+'/'+str(k))
 else:yield p,v
for n,x in enumerate(a['paths']):
 b=(P/x['identity']['path']).read_bytes()
 if x['identity']['path'].endswith('.json'):d=json.loads(b)
 else:
  rows=list(csv.DictReader(io.StringIO(b.decode()),delimiter='\\t'))
  for row in rows:
   for k,v in row.items():
    if v and v[0] in '[{':
     try:row[k]=json.loads(v)
     except ValueError:pass
  d={'rows':rows}
 prefixes={z['pointer'] for z in p if z['document']==n}
 for ptr,v in walk(d):
  parts=ptr.split('/');covered=any('/'.join(parts[:i]) in prefixes for i in range(1,len(parts)+1))
  if not covered:
   z={'document':n,'id':x['id'],'pointer':ptr,'type':type(v).__name__,'value_sha256':dh(v)}
   if isinstance(v,(list,dict)) and not v:empty.append(z)
   else:missing.append(z)
(T/'empty-structure-review.json').write_text(json.dumps({'purpose':'Exact empty listed set/object at the original parent generation; not evidence of absence of a feature/runtime effects. Enclosing owner/control and same-round qualified clauses remain separate.','entries':empty},ensure_ascii=False,indent=2)+'\\n')
(T/'coverage-precheck.json').write_text(json.dumps({'unrepresented_nonempty':missing,'empty_structures':len(empty)},ensure_ascii=False,indent=2)+'\\n')
print('NONEMPTY_UNREPRESENTED',len(missing),missing[:10]);print('COMPLETE_EMPTY_STRUCTURE_PURPOSES')
for (doc,key,typ),num in sorted(collections.Counter((z['id'],z['pointer'].rsplit('/',1)[-1],z['type']) for z in empty).items()):print(doc,key,typ,'COUNT',num,'FULL_VALUE', '[]' if typ=='list' else '{}')
